using P=pair<long long,long long>;
 assert(maiorAreaDobrada(5,8,array<P,4>{P{1,2},P{2,4},P{1,6},P{4,5}})==25);
 assert(maiorAreaDobrada(10,7,array<P,4>{P{3,9},P{1,7},P{1,4},P{4,6}})==42);
 assert(maiorAreaDobrada(1000000,1000000,array<P,4>{P{1,999999},P{1,2},P{1,2},P{1,2}})==999998000000LL);
 // Oráculo geométrico independente: todas as trincas de todos os subconjuntos
 // com >=2 pontos por lado em retângulos pequenos.
 for(int w=3;w<=5;++w)for(int h=3;h<=5;++h){
  vector<vector<int>> xs,ys;
  for(int mask=0;mask<(1<<(w-1));++mask){vector<int> a;for(int x=1;x<w;++x)if(mask&(1<<(x-1)))a.push_back(x);if(a.size()>=2)xs.push_back(a);}
  for(int mask=0;mask<(1<<(h-1));++mask){vector<int> a;for(int y=1;y<h;++y)if(mask&(1<<(y-1)))a.push_back(y);if(a.size()>=2)ys.push_back(a);}
  for(const auto&a:xs)for(const auto&b:xs)for(const auto&c:ys)for(const auto&d:ys){
   array<P,4> e={P{a.front(),a.back()},P{b.front(),b.back()},P{c.front(),c.back()},P{d.front(),d.back()}};
   vector<array<long long,3>> pontos;
   for(int x:a)pontos.push_back({x,0,0});for(int x:b)pontos.push_back({x,h,1});
   for(int y:c)pontos.push_back({0,y,2});for(int y:d)pontos.push_back({w,y,3});
   long long brute=0;
   for(size_t i=0;i<pontos.size();++i)for(size_t j=i+1;j<pontos.size();++j)for(size_t k=j+1;k<pontos.size();++k){
    auto a1=pontos[i],b1=pontos[j],c1=pontos[k];
    int iguais=(a1[2]==b1[2])+(a1[2]==c1[2])+(b1[2]==c1[2]);if(iguais!=1)continue;
    long long area=llabs((b1[0]-a1[0])*(c1[1]-a1[1])-(b1[1]-a1[1])*(c1[0]-a1[0]));brute=max(brute,area);
   }
   assert(maiorAreaDobrada(w,h,e)==brute);
  }
 }

