 // Referência independente por ordenação; exaustivo com negativos e duplicatas.
 auto oracle=[](vector<int> v){if(v.empty())return 0;sort(v.begin(),v.end());int best=1,len=1;for(size_t i=1;i<v.size();++i){if(v[i]==v[i-1])continue;if((long long)v[i]==(long long)v[i-1]+1)++len;else len=1;best=max(best,len);}return best;};
 for(int n=0;n<=7;++n){int total=1;for(int i=0;i<n;++i)total*=5;for(int mask=0;mask<total;++mask){vector<int> v(n);int t=mask;for(int&i:v){i=t%5-2;t/=5;}assert(maiorSequenciaConsecutiva(v)==oracle(v));}}
 vector<int> grande(50000,-10000);for(int i=-10000;i<40000;++i)grande.push_back(i);
 assert(maiorSequenciaConsecutiva(grande)==50000);

