// Oráculo: todas as injeções em coordenadas [-3,3] sem zero, para até 5 prédios.
for(int n=1;n<=5;++n){int count=1;for(int i=0;i<n;++i)count*=3;for(int mask=0;mask<count;++mask){vector<int> a(n);int z=mask;for(int&v:a){v=z%3;z/=3;}long long melhor=LLONG_MAX;function<void(int,int,long long)> dfs=[&](int i,int used,long long custo){if(i==n){melhor=min(melhor,custo);return;}for(int j=0;j<6;++j)if(!(used&(1<<j))){int coord=j<3?j-3:j-2;dfs(i+1,used|(1<<j),custo+2LL*abs(coord)*a[i]);}};dfs(0,0,0);assert(check(a)==melhor);}}
